clear;
clc;
close all;

%%%%%1a

x = (2*rand(1,200)-1).*sqrt(pi/2);
y = (2*rand(1,200)-1).*sqrt(pi/2);

x = sort(x);
y = sort(y);

[X,Y] = meshgrid(x,y);

Z = sin(X.^2 + Y.^2);

figure; %[output:6db91131]
surf(X,Y,Z); %[output:6db91131]
shading interp; %[output:6db91131]
colormap parula; %[output:6db91131]
view(50,50); %[output:6db91131]
grid on; %[output:6db91131]

xlabel('x'); %[output:6db91131]
ylabel('y'); %[output:6db91131]
zlabel('f(x,y)'); %[output:6db91131]
title('f(x,y) = sin(x^2 + y^2)'); %[output:6db91131]
colorbar; %[output:6db91131]


%%%%%1b

x = linspace(-2,1,100);
y = linspace(-2,1,100);

[X,Y] = meshgrid(x,y);

Z = 1 - 2*X.^2 - 3*Y.^2;

figure; %[output:1c1be3b0]
surf(X,Y,Z); %[output:1c1be3b0]
shading interp; %[output:1c1be3b0]
colormap turbo; %[output:1c1be3b0]
view(60,60); %[output:1c1be3b0]
grid on; %[output:1c1be3b0]

xlabel('x'); %[output:1c1be3b0]
ylabel('y'); %[output:1c1be3b0]
zlabel('f(x,y)'); %[output:1c1be3b0]
title('f(x,y) = 1 - 2x^2 - 3y^2'); %[output:1c1be3b0]
colorbar; %[output:1c1be3b0]

